/// Get pickups by category
pub fn get_pickups_by_category(category: PickupCategory) -> Vec<&'static WorldPickup> {
    WORLD_PICKUPS.iter().filter(|p| p.category == category).collect()
}

/// Get pickups by region
pub fn get_pickups_by_region(region: &str) -> Vec<&'static WorldPickup> {
    WORLD_PICKUPS.iter().filter(|p| p.region == region).collect()
}

/// Get pickup by event flag
pub fn get_pickup_by_flag(event_flag: u32) -> Option<&'static WorldPickup> {
    WORLD_PICKUPS.iter().find(|p| p.event_flag == event_flag)
}

/// Get all unique regions
pub fn get_all_regions() -> Vec<&'static str> {
    let mut regions: Vec<_> = WORLD_PICKUPS.iter()
        .map(|p| p.region)
        .collect::<std::collections::HashSet<_>>()
        .into_iter()
        .collect();
    regions.sort();
    regions
}

/// Get category counts
pub fn get_category_counts() -> Vec<(PickupCategory, usize)> {
    use std::collections::HashMap;
    let mut counts: HashMap<PickupCategory, usize> = HashMap::new();
    for pickup in WORLD_PICKUPS {
        *counts.entry(pickup.category).or_insert(0) += 1;
    }
    let mut result: Vec<_> = counts.into_iter().collect();
    result.sort_by(|a, b| b.1.cmp(&a.1));
    result
}
